WITH filtered AS (SELECT id, store_id, product_id, sale_date, units, ADD_MONTHS(sale_date, 12) AS sale_date_plus_months, GREATEST(units, revenue) AS greatest_units_revenue FROM store_sales WHERE revenue BETWEEN 2300 AND 2800) SELECT *, LEAD(greatest_units_revenue, 1) OVER (PARTITION BY store_id ORDER BY units, id) AS next_greatest_units_revenue, ROW_NUMBER() OVER (ORDER BY greatest_units_revenue, id) AS seq_no FROM filtered
